import abc
import re

import six
from moler.cmd.commandtextualgeneric import CommandTextualGeneric
from moler.exceptions import CommandFailure, ParsingDone


@six.add_metaclass(abc.ABCMeta)
class GenericAashell(CommandTextualGeneric):
    """GenericAashell command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        GenericAashell.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(GenericAashell, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self._re_parse_error = re.compile(
            r"(?P<ERROR>error.*|fail.*|Cannot execute the command.*|is not a valid command.*|Invalid option.*)", re.IGNORECASE
        )

    def on_new_line(self, line, is_full_line):
        """
        To parse command output. will be called after line with command echo.

        Write your own implementation but don't forget to call on_new_line from base class.

        :param line: Line to parse, new lines are trimmed
        :param is_full_line:  False for chunk of line; True on full line (NOTE: new line character removed)
        :return: None
        """
        if is_full_line:
            try:
                self._parse_error(line)
            except ParsingDone:
                pass
        return super(GenericAashell, self).on_new_line(line, is_full_line)

    def _parse_error(self, line):
        if self._regex_helper.search_compiled(self._re_parse_error, line):
            self.set_exception(CommandFailure(self, f"ERROR: {self._regex_helper.group('ERROR')}"))
            raise ParsingDone
